const localDate = (value, timeZone) => {
    const parts = new Intl.DateTimeFormat('en-US', {
        timeZone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
    }).formatToParts(value);
    const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
    return `${values.year}-${values.month}-${values.day}`;
};

const STORE = 'persistent';
const PENDING_KEY = 'external_lighting_recovery_pending_v1';
const pending = flow.get(PENDING_KEY, STORE);
const action = msg.payload?.event?.action ?? msg.payload?.action ?? msg.event?.action ?? null;

if (!pending || typeof action !== 'string') return null;

const now = new Date();
const timeZone = env.get('TZ') || 'America/Sao_Paulo';
if (Number(pending.expiresAt) <= now.getTime() || pending.localDate !== localDate(now, timeZone)) {
    flow.set(PENDING_KEY, null, STORE);
    node.status({ fill: 'grey', shape: 'ring', text: 'confirmação expirada' });
    return null;
}

if (action === pending.cancelAction) {
    flow.set(PENDING_KEY, null, STORE);
    node.status({ fill: 'blue', shape: 'ring', text: 'usuário optou por não ligar' });
    return null;
}

if (action !== pending.confirmAction) return null;

flow.set(PENDING_KEY, null, STORE);
msg.external_lighting_recovery_confirmed = true;
node.status({ fill: 'green', shape: 'dot', text: 'ligação confirmada' });
return msg;

msg.operation = "start";
msg.attempt = Number(msg.attempt || 1);
msg.start_source = msg.start_source || "temperature_threshold";
msg.trigger_temperature = Number(msg.payload);
return msg;

msg.operation = "startup";
msg.attempt = Number(msg.attempt || 1);
msg.start_source = "startup_reconciliation";
return msg;

const temperature = Number(msg.cpu_temperature);
const owner = msg.cooling_owner;
let pendingSnapshot = null;

if (typeof msg.stored_snapshot === "string") {
    const rawSnapshot = msg.stored_snapshot.trim();
    const transientStates = new Set(["", "unknown", "unavailable", "none", "null"]);
    if (!transientStates.has(rawSnapshot.toLowerCase())) {
        try {
            const parsed = JSON.parse(rawSnapshot);
            if (parsed && typeof parsed.state === "string") pendingSnapshot = parsed;
            else node.warn("Snapshot pendente inválido no startup: contrato ausente");
        } catch (error) {
            node.warn("Snapshot pendente inválido no startup: " + error.message);
        }
    }
}

if (!Number.isFinite(temperature)) {
    node.warn("Reconciliação ignorada: temperatura da CPU inválida.");
    return null;
}

msg.trigger_temperature = temperature;
if (temperature > 81.9) {
    msg.operation = "start";
    msg.start_source = "startup_reconciliation";
    if (owner === "off" && pendingSnapshot) msg.previous_climate = pendingSnapshot;
    return [msg, null];
}

if (owner === "on" && temperature < 70) {
    msg.operation = "stop";
    msg.stop_source = "startup_reconciliation";
    return [null, msg];
}

if (owner === "off" && temperature < 70 && pendingSnapshot) {
    msg.operation = "rollback";
    msg.stop_source = "startup_incomplete_acquisition";
    msg.previous_climate = pendingSnapshot;
