msg.context_force_recovery = msg.payload?.force_recovery === true;
msg.context_require_lighting = msg.payload?.require_lighting_ready === true;
msg.context_request_reason = msg.payload?.reason || "startup_or_periodic_reconciliation";
return msg;

const pending = msg.context_pending;
pending.force_recovery = true;
pending.require_lighting_ready = pending.require_lighting_ready === true || msg.context_require_lighting;
pending.request_reason = msg.context_request_reason;
flow.set(msg.context_pending_key, pending);
node.status({ fill: "yellow", shape: "ring", text: "ciclo em voo promovido para recovery" });
return null;

const testMode = msg._location_test === true;
const clockKey = testMode ? "refresh_cycle_clock__test" : "refresh_cycle_clock";
const previous = Number(flow.get(clockKey) || 0);
const cycle = Math.max(msg.context_now, Number.isFinite(previous) ? previous + 1 : 0);
flow.set(clockKey, cycle);
const pending = {
    cycle, people_received: false, vehicle_primary_received: false,
    people_ready: false, vehicle_primary_ready: false, emitted: false,
