    lifecycle.cooldown_until <= now || lifecycle.cooldown_until > now + cooldownMaxMs)) lifecycle.cooldown_until = null;
msg._light_reconcile = { now, policy, location_policy: locationPolicy, future_ms: futureMs,
    lifecycle, physical_signal: msg.payload?.kind === "light_physical", physical_accepted: true };
return msg;

const data = msg._light_reconcile;
const lifecycle = data.lifecycle;
const now = data.now;
if (data.physical_signal && flow.get("security_light_startup_logged") !== true) {
    node.log?.("iluminacao_seguranca: startup/reconciliação física iniciada");
    flow.set("security_light_startup_logged", true);
}
if (data.physical_signal) {
    const state = msg.payload.state;
    const updatedAt = Number(msg.payload.updated_at ?? 0);
    const previousAt = Number(flow.get("security_light_physical_updated_at") ?? 0);
    if (updatedAt > now + data.future_ms || (updatedAt && previousAt && updatedAt < previousAt) ||
        (updatedAt && previousAt && updatedAt === previousAt &&
        flow.get("security_light_physical_state") !== undefined &&
        flow.get("security_light_physical_state") !== state)) {
        flow.set("light_reconciled", false);
        data.physical_accepted = false;
        node.warn("iluminacao_seguranca: leitura física fora de ordem, futura ou conflitante; descartada");
    } else {
        flow.set("security_light_physical_observed_at", now);
        if (updatedAt) flow.set("security_light_physical_updated_at", updatedAt);
        flow.set("security_light_physical_state", state ?? "unknown");
        if (["on", "off"].includes(state)) {
            flow.set("light_reconciled", true);
            flow.set("security_light_last_unavailable_state", null);
            flow.set("security_light_turn_on_notification_latch_v1", state === "on"
                ? { version: 1, latched: true, reason: "physical_on", latched_at: now }
                : null, "persistent");
            if (state === "off" && lifecycle.active_by_arrival === true) {
                Object.assign(lifecycle, { active_by_arrival: false, on_since: null, force_off_at: null,
                    pending_off_at: null, pending_off_reason: null, pending_off_source: null,
                    cooldown_until: now + Number(data.policy.post_off_cooldown_minutes) * 60000,
                    updated_at: now });
                node.warn("iluminacao_seguranca: contexto ON corrigido porque o refletor físico está OFF");
            }
        } else {
            flow.set("light_reconciled", false);
            const previous = flow.get("security_light_last_unavailable_state");
            if (previous !== (state ?? "unknown")) node.warn(`iluminacao_seguranca: refletor ${state ?? "unknown"}; efeitos físicos bloqueados`);
            flow.set("security_light_last_unavailable_state", state ?? "unknown");
        }
    }
}
flow.set("security_light_lifecycle_v1", lifecycle, "persistent");
return msg;

const data = msg._light_reconcile;
const observedAt = Number(flow.get("security_light_physical_observed_at") ?? 0);
const freshMs = Number(data.policy.physical_fresh_seconds) * 1000;
const physicalFresh = Number.isFinite(observedAt) && observedAt <= data.now + data.future_ms &&
    data.now - observedAt <= freshMs;
if (!physicalFresh) flow.set("light_reconciled", false);
const people = flow.get("people_context_v1") ?? {};
const vehicle = flow.get("vehicle_primary_context_v1") ?? {};
const ready = people.ready === true && vehicle.ready === true && flow.get("sun_ready") === true &&
    flow.get("light_reconciled") === true && physicalFresh;
const wasReady = flow.get("security_light_ready");
flow.set("security_light_ready", ready);
if (wasReady !== ready) node.log?.(`iluminacao_seguranca: readiness ${ready ? "completo" : "pendente"}`);
data.recovery_needed = data.physical_accepted && ready &&
    flow.get("security_light_physical_state") === "on" && data.lifecycle.active_by_arrival === true;
data.deadlines = data.recovery_needed ? [
    Number.isFinite(data.lifecycle.force_off_at)
        ? { type: "backstop", at: data.lifecycle.force_off_at, reason: "recovered_backstop" } : null,
    Number.isFinite(data.lifecycle.pending_off_at)
        ? { type: "pending_off", at: data.lifecycle.pending_off_at,
            reason: data.lifecycle.pending_off_reason ?? "recovered_pending_off" } : null
].filter(Boolean) : [];
data.recovery_needed = data.deadlines.length > 0;
return msg;

const data = msg._light_reconcile;
const scheduled = flow.get("security_light_recovery_scheduled") ?? {};
const current = Object.fromEntries(data.deadlines.map((deadline) => [deadline.type, deadline.at]));
for (const type of Object.keys(scheduled)) if (scheduled[type] !== current[type]) delete scheduled[type];
data.messages = [];
for (const deadline of data.deadlines) {
    if (scheduled[deadline.type] === deadline.at) continue;
    scheduled[deadline.type] = deadline.at;
    data.messages.push({ payload: { event: "turn_off", reason: deadline.reason,
        deadline_type: deadline.type, recovered: true }, delay: Math.max(0, deadline.at - data.now) });
}
flow.set("security_light_recovery_scheduled", scheduled);
return msg;
